-- W6 (#199): the wilds' resource nodes, from the land.
--
-- `engine::node_spawn::plan` places each resource that grows in the
-- Wilderness where its habitat in backend/content/wilds.toml says: iron veins
-- high on the bare, steep rock of the ranges, stone on the scree below the
-- crags, old-growth trees on the valley floors, fallen branches under them,
-- and clay on the banks of the wild rivers, streams and lakes. Every node is
-- 30 clear of the trails and the water (clay 18 from the water), on ground no
-- steeper than a walker can climb, and where a walker from the rural edge can
-- get to. A node's base quality rises with depth and height, by the quality
-- table in wilds.toml.
--
-- The rows come from the ignored test `print_new_nodes`, and
-- `the_migration_writes_the_default_plan` checks they still match the plan.
-- They're on the 12000 world, after W1's shift. The rest of the plan (E2.3's
-- rows) is unchanged: the wilds are placed after every other zone.
--
--   tree 4064, fallen_branches 2032, rock_outcrop 1355, iron_vein 542,
--   clay_bank 271, all in the Wilderness
--
-- They wait in resource_node_seeds, as E2.3's did, until startup's content
-- sync has made their types (`node_spawn::plant_seeds`, #207). The ids are
-- the plan's, so an admin regenerate of the default world re-plans the same
-- nodes, and planting twice adds nothing.
INSERT INTO resource_node_seeds (id, resource_type, position_x, position_y, base_quality)
